definition.script:
node {
    stage('Use DisCo shared services folder secrets') {
        withCredentials([
            string(credentialsId: 'disco-root-folder-secret', variable: 'DISCO_ROOT_SECRET'),
            string(credentialsId: 'disco-shared-services-secret', variable: 'DISCO_SHARED_SERVICES_SECRET')
        ]) {
            sh '''#!/bin/bash
            set -euo pipefail
            test -n "$DISCO_ROOT_SECRET"
            test -n "$DISCO_SHARED_SERVICES_SECRET"
            echo "DisCo shared services folder credential bindings succeeded"
            '''
        }
    }
}
